easy.code:
void f(int n) {
    if (n == 0) return;
    f(n - 1);
    System.out.print(n + " ");
}

int sum(int n) {
    if (n == 0) return 0;
    return n + sum(n - 1);
}

int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}

long factorial(int n) {
    // base case goes here
    return n * factorial(n - 1);
}

medium.code:
boolean isSorted(int[] a, int i) {
    if (i >= a.length - 1) return true;
    if (a[i] > a[i + 1]) return false;
    isSorted(a, i + 1);
    return true;
}

boolean isPal(String s) {
    if (s.length() <= 1) return true;
    if (s.charAt(0) != s.charAt(s.length() - 1)) return false;
    return isPal(s.substring(1, s.length() - 1));
}

void reverse(int[] a, int i) {
    int n = a.length;
    if (i > n / 2) return;
    int t = a[i];
    a[i] = a[n - 1 - i];
    a[n - 1 - i] = t;
    reverse(a, i + 1);
}

double pow(double x, int n) {
    if (n == 0) return 1;
    if (n % 2 == 0) return pow(x, n / 2) * pow(x, n / 2);
    return x * pow(x, n / 2) * pow(x, n / 2);
}

void g(int n) {
    if (n == 0) return;
    System.out.print(n + " ");
    g(n - 1);
    System.out.print(n + " ");
}

hard.code:
double pow(double x, int n) {
    if (n == 0) return 1;
    if (n < 0) return 1 / pow(x, -n);
    double half = pow(x, n / 2);
    return n % 2 == 0 ? half * half : half * half * x;
}

static int count = 0;

static int countDigits(int n) {
    if (n == 0) return count;
    count++;
    return countDigits(n / 10);
}

public static void main(String[] args) {
    System.out.println(countDigits(123) + " " + countDigits(45));
}

static long sum(int i, long acc) {
    if (i < 1) return acc;
    return sum(i - 1, acc + i);
}
